import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

type CommentNode = {
  id: string;
  text: string;
  children: CommentNode[];
};

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  comments: CommentNode[] = [];

  topDraft = '';

  activeReplyId: string | null = null;
  replyDraft = '';

  private nextId = 1;
  private makeId(): string {
    return String(this.nextId++);
  }

  addTop(): void {
    const text = this.topDraft.trim();
    if (!text) return;

    this.comments.unshift({ id: this.makeId(), text, children: [] });
    this.topDraft = '';
  }

  openReply(id: string): void {
    this.activeReplyId = id;
    this.replyDraft = '';
  }

  cancelReply(): void {
    this.activeReplyId = null;
    this.replyDraft = '';
  }

  submitReply(parentId: string): void {
    const text = this.replyDraft.trim();
    if (!text) return;

    const parent = this.findById(this.comments, parentId);
    if (!parent) return;

    parent.children.push({ id: this.makeId(), text, children: [] });
    this.cancelReply();
  }

  private findById(nodes: CommentNode[], id: string): CommentNode | null {
    for (const n of nodes) {
      if (n.id === id) return n;
      const found = this.findById(n.children, id);
      if (found) return found;
    }
    return null;
  }
}

